#include <chrono>

void gemv_ternary_neon_v24(const int8_t* __restrict W, const int8_t* __restrict X, int32_t* __restrict Y, int count) {
    int32x4_t acc0 = vdupq_n_s32(0);
    int32x4_t acc1 = vdupq_n_s32(0);

