        acc1 = vpadalq_s16(acc1, vmull_s8(vget_low_s8(w1), vget_low_s8(x1)));
        acc1 = vpadalq_s16(acc1, vmull_s8(vget_high_s8(w1), vget_high_s8(x1)));
    }

